import{_ as r,o as a,c as t,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"飞行控制器移植指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/hardware/porting_guide.md","filePath":"zh/hardware/porting_guide.md"}'),i={name:"zh/hardware/porting_guide.md"};function l(n,e,s,d,h,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="飞行控制器移植指南" tabindex="-1">飞行控制器移植指南 <a class="header-anchor" href="#飞行控制器移植指南" aria-label="Permalink to &quot;飞行控制器移植指南&quot;">​</a></h1><p>本主题主要针对希望将 PX4 移植到 <em>新</em> 飞控硬件平台上的开发人员。</p><h2 id="px4-架构" tabindex="-1">PX4 架构 <a class="header-anchor" href="#px4-架构" aria-label="Permalink to &quot;PX4 架构&quot;">​</a></h2><p>PX4 由两个主要层组成： 基于主机操作系统（NuttX、Linux 或任何其他 POSIX 平台如 Mac OS）的<a href="./../middleware/">板级支持与中间件层</a>，以及应用程序（位于<a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/modules" target="_blank" rel="noreferrer">src/modules</a>目录下的飞行栈）。 更多信息请参阅<a href="./../concept/architecture">PX4架构概述</a>。</p><p>本指南仅关注主机操作系统和中间件，因为 应用层/飞行控制栈 可以在任何目标平台上运行。</p><h2 id="飞行控制器配置文件分布位置" tabindex="-1">飞行控制器配置文件分布位置 <a class="header-anchor" href="#飞行控制器配置文件分布位置" aria-label="Permalink to &quot;飞行控制器配置文件分布位置&quot;">​</a></h2><p>板卡启动和配置文件位于每个板卡厂商专属目录下的 <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/" target="_blank" rel="noreferrer">/boards</a> 路径中（即 <strong>boards/<em>VENDOR</em>/<em>MODEL</em>/</strong>）。</p><p>例如，对于 FMUv5 飞控硬件平台：</p><ul><li>(所有) 板卡专用文件：<a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/px4/fmu-v5" target="_blank" rel="noreferrer">/boards/px4/fmu-v5</a>。</li><li>构建配置：<a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/default.px4board</a>。</li><li>板卡专用初始化文件：<a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/init/rc.board_defaults" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/init/rc.board_defaults</a><ul><li>如果在主板目录下找到位于<strong>init/rc.board</strong>的文件，则该主板专用的初始化文件会自动包含在启动脚本中。</li><li>该文件用于启动仅存在于特定主板上的传感器 (和其他东西)。 它也可用于设置电路板的默认参数、UART映射以及任何其他特殊情况。</li><li>对于FMUv5，您可以看到所有Pixhawk 4传感器均已启动，同时它还设置了更大的LOGGER_BUF缓冲区。</li></ul></li></ul><h2 id="主机操作系统配置" tabindex="-1">主机操作系统配置 <a class="header-anchor" href="#主机操作系统配置" aria-label="Permalink to &quot;主机操作系统配置&quot;">​</a></h2><p>本节介绍了移植每个受支持的主机操作系统到新的飞控板硬件平台上需要用到的配置文件的用途和所处位置。</p><h3 id="nuttx" tabindex="-1">NuttX <a class="header-anchor" href="#nuttx" aria-label="Permalink to &quot;NuttX&quot;">​</a></h3><p>参见<a href="./porting_guide_nuttx">NuttX 板移植指南</a>。</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>基于 Linux 的飞控板不包含任何 操作系统和内核的配置。 这些功能已由该开发板可用的Linux镜像提供（该镜像需开箱即支持惯性传感器）。</p><ul><li><a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/raspberrypi/default.px4board" target="_blank" rel="noreferrer">boards/px4/raspberrypi/default.px4board</a> - RPi 交叉编译。 </li></ul><h2 id="中间件组件和配置" tabindex="-1">中间件组件和配置 <a class="header-anchor" href="#中间件组件和配置" aria-label="Permalink to &quot;中间件组件和配置&quot;">​</a></h2><p>本节介绍各类中间件组件，以及将它们移植到新的飞行控制器硬件所需更新的配置文件。</p><h3 id="qurt-hexagon" tabindex="-1">QuRT / Hexagon <a class="header-anchor" href="#qurt-hexagon" aria-label="Permalink to &quot;QuRT / Hexagon&quot;">​</a></h3><ul><li>启动脚本位于 <a href="https://github.com/PX4/PX4-Autopilot/tree/main/posix-configs" target="_blank" rel="noreferrer">posix-configs/</a>。 </li><li>操作系统配置是默认 Linux 镜像的一部分（TODO: 需要提供 LINUX 镜像文件位置和程序烧写指南）。</li><li>PX4 中间件配置位于<a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards" target="_blank" rel="noreferrer">src/boards</a>。 TODO: 添加BUS CONFIG</li></ul><h2 id="rc-uart-接线建议" tabindex="-1">RC UART 接线建议 <a class="header-anchor" href="#rc-uart-接线建议" aria-label="Permalink to &quot;RC UART 接线建议&quot;">​</a></h2><p>通常建议通过独立的RX和TX引脚将RC连接至微控制器。但若RX和TX引脚连接在一起，则必须将UART置于单线模式以避免竞争冲突。此操作需通过板级配置文件和清单文件实现。示例可参考<a href="https://github.com/PX4/Firmware/blob/master/src/drivers/boards/px4fmu-v5/manifest.c">px4fmu-v5</a>。 如果 RX 和 TX 连在了一起，那么 UART 需要设置为单线模式以防止出现争用。 这可以用过对飞控板的配置文件和 manifest 文件进行更改来实现。 一个例子是 <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/src/manifest.c" target="_blank" rel="noreferrer">px4fmu-v5</a>。 </p><h2 id="getting-your-board-supported" tabindex="-1">Getting Your Board Supported <a class="header-anchor" href="#getting-your-board-supported" aria-label="Permalink to &quot;Getting Your Board Supported&quot;">​</a></h2><p>This page covers the <em>technical</em> work of porting PX4 to new hardware. The <em>process</em> for getting that port reviewed, merged, and listed on the PX4 website, including board IDs, USB VID/PID, flight-test evidence, and maintenance expectations, is documented separately:</p><ul><li><a href="./../hardware/board_support_guide">Manufacturer&#39;s PX4 Board Support Guide</a></li></ul><p>In short: build your own firmware target based on PX4, demonstrate stable flight on the current release, and open a pull request with your board support code, documentation, and flight logs. The board support guide explains each step.</p><p>The PX4 project supports and maintains the <a href="./../hardware/reference_design">FMU standard reference hardware</a> and any boards compatible with the standard, including the <a href="./../flight_controller/pixhawk_series">Pixhawk series</a> (see the <a href="./../flight_controller/">full list of supported hardware</a>). Boards merged into PX4 benefit from a port in the repository, firmware builds accessible from <em>QGroundControl</em>, compatibility with the rest of the ecosystem, and automated CI checks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The cost of maintaining a port is proportional to how far it diverges from the standard. Consider that cost before deviating: staying close to the reference design lets you benefit from day-to-day PX4 development with minimal maintenance burden.</p></div><p>Manufacturers are responsible for keeping their port up to date and working across PX4 releases. The PX4 project reserves the right to refuse or remove ports that do not meet the project&#39;s requirements, and all contributors are expected to follow the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</p><h2 id="相关信息" tabindex="-1">相关信息 <a class="header-anchor" href="#相关信息" aria-label="Permalink to &quot;相关信息&quot;">​</a></h2><ul><li><a href="./../middleware/drivers">设备驱动程序</a> - 如何支持新的外围硬件（设备驱动程序）</li><li><a href="./../dev_setup/building_px4">构建代码</a> - 如何构建源代码并上传固件</li><li>受支持的飞行控制器： <ul><li><a href="./../flight_controller/">自动驾驶仪硬件</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/#supported-hardware" target="_blank" rel="noreferrer">支持的主板列表</a> (Github) - PX4-Autopilot 拥有专用代码的开发板</li></ul></li><li><a href="./../peripherals/">支持的外设</a></li></ul>',31)])])}const b=r(i,[["render",l]]);export{c as __pageData,b as default};
